#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// GEMM kernel with split-K reduction.
// A: (M,K) row-major, stride (K,1)
// B: (K,N) row-major, stride (N,1)
// C: (M,N) row-major, stride (N,1), accumulated via atomicAdd across K-splits.
template <class TA, class TB, class TC>
__global__ static void
gemm_splitk_device(int M, int N, int K,
                    TA const* A,
                    TB const* B,
                    TC      * C,
                    int split_k, int k_tiles_total)
{
  constexpr int BLK_M = 128;
  constexpr int BLK_N = 128;
  constexpr int BLK_K = 8;
  // Represent full tensors.
  // mA: (M,K) with A row-major stride (K,1)
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(M, K), make_stride(K, Int<1>{}));
  // mB viewed as (N,K): mB(n,k) = B[k*N + n]  => stride (1, N)
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(N, K), make_stride(Int<1>{}, N));
  // mC: (M,N) row-major stride (N,1)
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(M, N), make_stride(N, Int<1>{}));
  auto cta_tiler = make_shape(Int<BLK_M>{}, Int<BLK_N>{}, Int<BLK_K>{});
  auto cta_coord = make_coord(blockIdx.x, blockIdx.y, _);
  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1, X, _1>{});  // (BLK_M, BLK_K, k_tiles_total)
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step< X,_1, _1>{});  // (BLK_N, BLK_K, k_tiles_total)
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1,_1,  X>{});  // (BLK_M, BLK_N)
  // Double-buffered shared memory to enable software pipelining of
  // global->shared loads with the previous tile's compute (cp.async).
  __shared__ __align__(16) TA smemA[2][BLK_M * BLK_K];
  __shared__ __align__(16) TB smemB[2][BLK_N * BLK_K];
  Tensor sA0 = make_tensor(make_smem_ptr(smemA[0]), make_shape(Int<BLK_M>{}, Int<BLK_K>{}), make_stride(Int<BLK_K>{}, Int<1>{}));
  Tensor sA1 = make_tensor(make_smem_ptr(smemA[1]), make_shape(Int<BLK_M>{}, Int<BLK_K>{}), make_stride(Int<BLK_K>{}, Int<1>{}));
  Tensor sB0 = make_tensor(make_smem_ptr(smemB[0]), make_shape(Int<BLK_N>{}, Int<BLK_K>{}), make_stride(Int<1>{}, Int<BLK_N>{}));
  Tensor sB1 = make_tensor(make_smem_ptr(smemB[1]), make_shape(Int<BLK_N>{}, Int<BLK_K>{}), make_stride(Int<1>{}, Int<BLK_N>{}));
  auto tA = make_layout(make_shape(Int<128>{}, Int<2>{}));  // 128x2 thread layout: gives each thread 4 contiguous K-elements of A for float4 vectorized loads
  auto tB = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));
  // Recast A/B global->shared copy tensors to float4 for vectorized 128-bit loads.
  // IMPORTANT: recast BEFORE partitioning by thread. local_partition uses a
  // raked/coset partition, so recasting an already-partitioned per-thread
  // tensor does not correspond to actually-contiguous memory and produces
  // misaligned addresses. Instead, recast the whole CTA tile first (which
  // shrinks the contiguous mode by the vector width), then partition with
  // thread layouts sized so each thread owns exactly one float4 element.
  // A's K dimension is contiguous (row-major stride (K,1)): gA (BLK_M,BLK_K,k_tiles)
  // -> gA4 (BLK_M, BLK_K/4, k_tiles) = (128, 2, k_tiles_total), matching tA=(128,2).
  // B's N dimension is contiguous (mB stride (1,N)): gB (BLK_N,BLK_K,k_tiles)
  // -> gB4 (BLK_N/4, BLK_K, k_tiles) = (32, 8, k_tiles_total), matching tB=(32,8).
  Tensor gA4  = recast<float4>(gA);
  Tensor sA04 = recast<float4>(sA0);
  Tensor sA14 = recast<float4>(sA1);
  Tensor gB4  = recast<float4>(gB);
  Tensor sB04 = recast<float4>(sB0);
  Tensor sB14 = recast<float4>(sB1);
  Tensor tAgA4  = local_partition(gA4,  tA, threadIdx.x);
  Tensor tAsA04 = local_partition(sA04, tA, threadIdx.x);
  Tensor tAsA14 = local_partition(sA14, tA, threadIdx.x);
  Tensor tBgB4  = local_partition(gB4,  tB, threadIdx.x);
  Tensor tBsB04 = local_partition(sB04, tB, threadIdx.x);
  Tensor tBsB14 = local_partition(sB14, tB, threadIdx.x);
  Tensor tCsA0 = local_partition(sA0, tC, threadIdx.x, Step<_1, X>{});
  Tensor tCsA1 = local_partition(sA1, tC, threadIdx.x, Step<_1, X>{});
  Tensor tCsB0 = local_partition(sB0, tC, threadIdx.x, Step< X,_1>{});
  Tensor tCsB1 = local_partition(sB1, tC, threadIdx.x, Step< X,_1>{});
  Tensor tCgC  = local_partition(gC, tC, threadIdx.x, Step<_1,_1>{});
  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);
  // Split the K-tile range among blockIdx.z
  int k_tile_start = (int)((long long)blockIdx.z * k_tiles_total / split_k);
  int k_tile_end   = (int)((long long)(blockIdx.z + 1) * k_tiles_total / split_k);
  if (k_tile_start < k_tile_end) {
    // Prologue: prefetch the first K-tile into buffer 0.
    copy(tAgA4(_, _, k_tile_start), tAsA04);
    copy(tBgB4(_, _, k_tile_start), tBsB04);
    cp_async_fence();
    int cur_buf = 0;
    for (int k_tile = k_tile_start; k_tile < k_tile_end; ++k_tile) {
      int next_buf = cur_buf ^ 1;
      if (k_tile + 1 < k_tile_end) {
        // Prefetch next tile into the other buffer while we compute the current one.
        if (next_buf == 0) {
          copy(tAgA4(_, _, k_tile + 1), tAsA04);
          copy(tBgB4(_, _, k_tile + 1), tBsB04);
        } else {
          copy(tAgA4(_, _, k_tile + 1), tAsA14);
          copy(tBgB4(_, _, k_tile + 1), tBsB14);
        }
        cp_async_fence();
        cp_async_wait<1>();
      } else {
        cp_async_wait<0>();
      }
      __syncthreads();
      if (cur_buf == 0) {
        gemm(tCsA0, tCsB0, tCrC);
      } else {
        gemm(tCsA1, tCsB1, tCrC);
      }
      __syncthreads();
      cur_buf = next_buf;
    }
  }
  // Atomic accumulation into global C (needed because of split-K reduction)
  CUTE_UNROLL
  for (int i = 0; i < size(tCrC); ++i) {
    atomicAdd(&tCgC(i), tCrC(i));
  }
}

